// Unit 16 (Repeater) browser pass: two tabs, rename, send from each, option change,
// redirect chain + hop choice, change highlight. Usage: node e2e.js <base> <victim> <redirector>
const { chromium } = require('playwright');
const base = process.argv[2], victim = process.argv[3], redir = process.argv[4];
const out = __dirname;
(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('response', (r) => { if (r.status() >= 400 && r.url().startsWith(base)) errors.push(r.status() + ' ' + r.url()); });
  const ok = (cond, msg) => { if (!cond) { throw new Error('ASSERT: ' + msg); } console.log('ok -', msg); };

  await page.goto(base + '/ui2/repeater');
  ok(await page.locator('text=unsaved draft').count() === 1, 'virtual tab on an empty workspace');
  // Tab 1: send to the victim with Ctrl+Space from the textarea.
  await page.fill('textarea[name=raw]', `GET /tab-one HTTP/1.1\nHost: ${victim}\n\n`);
  await page.focus('textarea[name=raw]');
  await page.keyboard.press('Control+Space');
  await page.waitForSelector('#rp-status');
  ok((await page.textContent('#rp-response-body')).includes('victim-ok'), 'tab 1 send rendered the victim response');

  // Tab 2 via +, rename it, send via the button.
  await page.click('#rp-new');
  await page.waitForFunction(() => document.querySelectorAll('.rp-tab').length === 2);
  await page.fill('textarea[name=raw]', `GET /tab-two HTTP/1.1\nHost: ${victim}\n\n`);
  await page.click('summary:has-text("Tab:")');
  await page.fill('input[name=name]', 'login');
  await page.click('#rp-rename');
  await page.waitForSelector('.rp-tab.active:has-text("login")');
  ok(true, 'second tab renamed to login');
  ok((await page.inputValue('textarea[name=raw]')).includes('/tab-two'), 'rename kept the unsent edit');
  await page.click('#rp-send');
  await page.waitForSelector('#rp-status');
  ok(true, 'tab 2 sent');

  // Back to tab 1 keeps its own response.
  await page.click('.rp-tab:not(.active)');
  await page.waitForFunction(() => document.querySelector('textarea[name=raw]').value.includes('/tab-one'));
  ok(true, 'switching back shows tab 1 draft');

  // Option change + redirect chain on tab 2.
  await page.click('.rp-tab:has-text("login")');
  await page.waitForFunction(() => document.querySelector('textarea[name=raw]').value.includes('/tab-two'));
  await page.fill('input[name=target]', 'http://' + redir);
  await page.fill('textarea[name=raw]', `GET /r HTTP/1.1\nHost: ${redir}\n\n`);
  await page.click('summary:has-text("Send options")');
  await page.check('input[name=opt_override]');
  await page.selectOption('select[name=opt_redirect]', 'always');
  await page.click('#rp-send');
  await page.waitForSelector('#rp-redirects');
  ok((await page.locator('#rp-redirects tbody tr').count()) >= 2, 'redirect chain table rendered');
  await page.screenshot({ path: out + '/repeater-redirects-1280.png', fullPage: true });
  await page.click('a.rp-hop');
  await page.waitForSelector('text=Hop 1 request');
  ok((await page.textContent('#rp-response-body')).includes('final-'), 'hop 1 response shown');

  // Send twice more and highlight changes.
  await page.fill('textarea[name=raw]', `GET /count HTTP/1.1\nHost: ${redir}\n\n`);
  await page.click('#rp-send');
  await page.waitForSelector('#rp-status');
  await page.click('#rp-send');
  await page.waitForSelector('#rp-diff-on');
  await page.click('#rp-diff-on');
  await page.waitForSelector('#rp-diff .d-add');
  ok(true, 'change highlighting shows added text');
  await page.click('#rp-back');
  await page.waitForSelector('#rp-fwd');
  ok(true, 'history back works');
  await page.screenshot({ path: out + '/repeater-1280.png', fullPage: true });

  await page.setViewportSize({ width: 390, height: 844 });
  await page.screenshot({ path: out + '/repeater-390.png', fullPage: true });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
  ok(!overflow, 'no horizontal overflow at 390px');

  ok(errors.length === 0, 'no console errors or 4xx/5xx: ' + errors.join('; '));
  await browser.close();
})().catch(async (e) => { console.error(e); process.exit(1); });

